// next/image loader for the static export: maps each requested width to the WebP file
// generated by scripts/optimize-images.mjs. Anything outside /images/ is served as is.
export default function imageLoader({ src, width }: { src: string; width: number }) {
  const match = src.match(/^\/images\/(.+)\.(jpe?g|png)$/i);
  if (!match) return src;
  return `/_optimized/images/${match[1]}-${width}.webp`;
}
